func:
/**
 * Chemical Dosing & Pre-treatment Engine
 * Stage 1: Alum (Coagulation / Pre-treatment)
 * Stage 3: Chlorine (Disinfection / Post-treatment)
 * Supports Volume & Timer triggers with safe hardware limits.
 */

// 1. Initialise / fetch persistent context settings
let config = flow.get('chem_config_v3') || {
    mode: 'HYBRID', // 'VOLUME_TRIGGER', 'TIMER_TRIGGER', or 'HYBRID'
    stage1_alum: {
        pump_rate_ml_sec: 1.0,       // 5 V peristaltic pump: 2 s = 2 mL (calibrate)
        ratio_ml_per_L: 3.0,         // 1 % alum stock: 3 mL per L water (~30 mg/L)
        min_dose_threshold_L: 0.2,   // rover tanks hold 400 mL: dose per 200 mL
        fixed_timer_dose_ml: 0.6,    // Dose for pure timer trigger
        max_single_dose_ml: 4.0,     // Safety ceiling per injection
        current_stock_ml: 250.0      // Reservoir level
    },
    stage3_chlorine: {
        pump_rate_ml_sec: 1.0,       // 5 V dosing pump (calibrate)
        ratio_ml_per_L: 3.0,         // 0.07 % NaOCl stock (bleach 1:50): 3 mL per L (~2 mg/L)
        min_dose_threshold_L: 0.2,   // rover tanks hold 400 mL: dose per 200 mL
        fixed_timer_dose_ml: 0.6,    // Dose for pure timer trigger
        max_single_dose_ml: 4.0,     // Safety ceiling per injection
        current_stock_ml: 250.0      // Reservoir level
    },
    accumulated_vol: {
        stage1: 0,
        stage3: 0
    },
    emergency_stop: false
};

let topic = msg.topic || '';
let payload = msg.payload || {};

// Handle Emergency Stop
if (topic === 'safety/estop') {
    config.emergency_stop = !!payload;
    flow.set('chem_config_v3', config);
    if (config.emergency_stop) {
        node.status({ fill: 'red', shape: 'dot', text: 'E-STOP ACTIVE! All pumps halted' });
        // Abort pumps immediately: Output 1 -> Alum off, Output 2 -> Chlorine off
        return [
            { topic: 'actuator/alum_pump/cmd', payload: 0, reason: 'ESTOP' },
            { topic: 'actuator/chlorine_pump/cmd', payload: 0, reason: 'ESTOP' },
            { topic: 'telemetry/dosing', payload: { status: 'ESTOP_ENGAGED' } }
        ];
    } else {
        node.status({ fill: 'green', shape: 'ring', text: 'E-STOP Released. System Ready' });
        return null;
    }
}

if (config.emergency_stop) {
    node.warn('Dosing rejected: Emergency stop active.');
    return null;
}

let alumTriggerMsg = null;
let chlorineTriggerMsg = null;
let telemetryMsg = null;

// CASE A: Water Volume Inflow Trigger (Pulse/Flowmeter)
if (topic.includes('stage1/inflow')) {
    let addedLiters = parseFloat(payload.volume_added_liters || 0);
    config.accumulated_vol.stage1 += addedLiters;

    // Check if accumulation reached dosing threshold
    if (config.accumulated_vol.stage1 >= config.stage1_alum.min_dose_threshold_L) {
        let targetLiters = config.accumulated_vol.stage1;
        let calcDoseMl = targetLiters * config.stage1_alum.ratio_ml_per_L;

        // Apply safety clamp
        calcDoseMl = Math.min(calcDoseMl, config.stage1_alum.max_single_dose_ml);
        calcDoseMl = Math.round(calcDoseMl * 100) / 100;

        // Compute run time (ms)
        let durationSec = calcDoseMl / config.stage1_alum.pump_rate_ml_sec;
        let durationMs = Math.round(durationSec * 1000);

        // Deduct stock
        config.stage1_alum.current_stock_ml -= calcDoseMl;
        config.accumulated_vol.stage1 = 0; // Reset batch accumulator

        alumTriggerMsg = {
            topic: 'actuator/alum_pump/run',
            payload: {
                target: 'Stage 1 (Coagulation/Pre-treatment)',
                chemical: 'Alum (Aluminum Sulfate)',
                trigger_mode: 'VOLUME',
                water_processed_L: targetLiters,
                dose_volume_ml: calcDoseMl,
                duration_ms: durationMs,
                pump_rate_ml_s: config.stage1_alum.pump_rate_ml_sec,
                stock_remaining_ml: config.stage1_alum.current_stock_ml,
                timestamp: new Date().toISOString()
            }
        };
    }
}
else if (topic.includes('stage3/inflow')) {
    let addedLiters = parseFloat(payload.volume_added_liters || 0);
    config.accumulated_vol.stage3 += addedLiters;

    if (config.accumulated_vol.stage3 >= config.stage3_chlorine.min_dose_threshold_L) {
        let targetLiters = config.accumulated_vol.stage3;
        let calcDoseMl = targetLiters * config.stage3_chlorine.ratio_ml_per_L;

        // Apply safety clamp
        calcDoseMl = Math.min(calcDoseMl, config.stage3_chlorine.max_single_dose_ml);
        calcDoseMl = Math.round(calcDoseMl * 100) / 100;

        // Compute run time (ms)
        let durationSec = calcDoseMl / config.stage3_chlorine.pump_rate_ml_sec;
        let durationMs = Math.round(durationSec * 1000);

        // Deduct stock
        config.stage3_chlorine.current_stock_ml -= calcDoseMl;
        config.accumulated_vol.stage3 = 0; // Reset batch accumulator

        chlorineTriggerMsg = {
            topic: 'actuator/chlorine_pump/run',
            payload: {
                target: 'Stage 3 (Disinfection)',
                chemical: 'Chlorine (Sodium Hypochlorite)',
                trigger_mode: 'VOLUME',
                water_processed_L: targetLiters,
                dose_volume_ml: calcDoseMl,
                duration_ms: durationMs,
                pump_rate_ml_s: config.stage3_chlorine.pump_rate_ml_sec,
                stock_remaining_ml: config.stage3_chlorine.current_stock_ml,
                timestamp: new Date().toISOString()
            }
        };
    }
}
// CASE B: Scheduled / Periodic Timer Trigger
else if (topic === 'trigger/timer') {
    // Timer-based dosing runs fixed or adaptive dose for Stage 1 and Stage 3
    let alumDose = config.stage1_alum.fixed_timer_dose_ml;
    let alumDurationMs = Math.round((alumDose / config.stage1_alum.pump_rate_ml_sec) * 1000);
    config.stage1_alum.current_stock_ml -= alumDose;

    alumTriggerMsg = {
        topic: 'actuator/alum_pump/run',
        payload: {
            target: 'Stage 1 (Coagulation)',
            chemical: 'Alum',
            trigger_mode: 'TIMER',
            dose_volume_ml: alumDose,
            duration_ms: alumDurationMs,
            stock_remaining_ml: config.stage1_alum.current_stock_ml,
            timestamp: new Date().toISOString()
        }
    };

    let chlorineDose = config.stage3_chlorine.fixed_timer_dose_ml;
    let chlorineDurationMs = Math.round((chlorineDose / config.stage3_chlorine.pump_rate_ml_sec) * 1000);
    config.stage3_chlorine.current_stock_ml -= chlorineDose;

    chlorineTriggerMsg = {
        topic: 'actuator/chlorine_pump/run',
        payload: {
            target: 'Stage 3 (Disinfection)',
            chemical: 'Chlorine',
            trigger_mode: 'TIMER',
            dose_volume_ml: chlorineDose,
            duration_ms: chlorineDurationMs,
            stock_remaining_ml: config.stage3_chlorine.current_stock_ml,
            timestamp: new Date().toISOString()
        }
    };
}

// Save updated state
flow.set('chem_config_v3', config);

// Status update on node
node.status({
    fill: 'green',
    shape: 'dot',
    text: `Stg1 Acc: ${config.accumulated_vol.stage1.toFixed(1)}L | Stg3 Acc: ${config.accumulated_vol.stage3.toFixed(1)}L`
});

// Compile telemetry
telemetryMsg = {
    topic: 'telemetry/dosing',
    payload: {
        accumulated_vol: config.accumulated_vol,
        alum_stock_ml: config.stage1_alum.current_stock_ml,
        chlorine_stock_ml: config.stage3_chlorine.current_stock_ml,
        estop: config.emergency_stop,
        last_event: topic
    }
};

// Outputs: [1: Alum Execution, 2: Chlorine Execution, 3: Telemetry/Dashboard]
return [alumTriggerMsg, chlorineTriggerMsg, telemetryMsg];

/**
 * Stage 1 Alum Pump Pulse Controller
 * Precision Relay / GPIO control with exact hardware pulse cutoff.
 */

let cmd = msg.payload;
let activeTimer = context.get('alum_timer_id');

// Handle forced abort or manual off
if (cmd === 0 || (typeof cmd === 'object' && cmd.action === 'OFF')) {
    if (activeTimer) {
        clearTimeout(activeTimer);
        context.set('alum_timer_id', null);
    }
    node.status({ fill: 'grey', shape: 'dot', text: 'Pump IDLE (Stopped)' });
    return { topic: 'hardware/relay/stage1_alum', payload: 0, state: 'OFF' };
}

if (typeof cmd === 'object' && cmd.duration_ms > 0) {
    let durationMs = cmd.duration_ms;
    let doseMl = cmd.dose_volume_ml;
    let triggerMode = cmd.trigger_mode;

    // Clear previous timer if still lingering
    if (activeTimer) {
        clearTimeout(activeTimer);
    }

    node.status({
        fill: 'blue',
        shape: 'dot',
        text: `Injecting ${doseMl} mL Alum (${(durationMs/1000).toFixed(1)}s via ${triggerMode})`
    });

    // 1. Immediately turn Relay / Pump ON
    node.send({ 
        topic: 'hardware/relay/stage1_alum',
        payload: 1, 
        state: 'ON',
        chemical: 'Alum',
        dose_ml: doseMl,
        duration_ms: durationMs 
    });

    // 2. Schedule precise non-blocking hardware cutoff
    let timerId = setTimeout(() => {
        node.status({ fill: 'green', shape: 'ring', text: `Dose complete (${doseMl} mL injected)` });
        node.send({ 
            topic: 'hardware/relay/stage1_alum',
            payload: 0, 
            state: 'OFF',
            chemical: 'Alum',
            completed_at: new Date().toISOString()
        });
        context.set('alum_timer_id', null);
    }, durationMs);

    context.set('alum_timer_id', timerId);
}

return null;

/**
 * Stage 3 Chlorine Pump Pulse Controller
 * Precision Relay / GPIO control with exact hardware pulse cutoff.
 */

let cmd = msg.payload;
let activeTimer = context.get('chlorine_timer_id');

// Handle forced abort or manual off
if (cmd === 0 || (typeof cmd === 'object' && cmd.action === 'OFF')) {
    if (activeTimer) {
        clearTimeout(activeTimer);
        context.set('chlorine_timer_id', null);
    }
    node.status({ fill: 'grey', shape: 'dot', text: 'Pump IDLE (Stopped)' });
    return { topic: 'hardware/relay/stage3_chlorine', payload: 0, state: 'OFF' };
}

if (typeof cmd === 'object' && cmd.duration_ms > 0) {
    let durationMs = cmd.duration_ms;
    let doseMl = cmd.dose_volume_ml;
    let triggerMode = cmd.trigger_mode;

    // Clear previous timer if still lingering
    if (activeTimer) {
        clearTimeout(activeTimer);
    }

    node.status({
        fill: 'yellow',
        shape: 'dot',
        text: `Injecting ${doseMl} mL Chlorine (${(durationMs/1000).toFixed(1)}s via ${triggerMode})`
    });

    // 1. Immediately turn Relay / Pump ON
    node.send({ 
        topic: 'hardware/relay/stage3_chlorine',
        payload: 1, 
        state: 'ON',
        chemical: 'Chlorine',
        dose_ml: doseMl,
        duration_ms: durationMs 
    });

    // 2. Schedule precise non-blocking hardware cutoff
    let timerId = setTimeout(() => {
        node.status({ fill: 'green', shape: 'ring', text: `Dose complete (${doseMl} mL injected)` });
        node.send({ 
            topic: 'hardware/relay/stage3_chlorine',
            payload: 0, 
            state: 'OFF',
            chemical: 'Chlorine',
            completed_at: new Date().toISOString()
        });
        context.set('chlorine_timer_id', null);
    }, durationMs);

    context.set('chlorine_timer_id', timerId);
}

return null;

// The ESP32 times the pump itself (DosingPump core), so only the dose volume is sent -
// network delay can no longer change the injected volume.
if (msg.state !== 'ON' || !msg.dose_ml) return null;
const pump = String(msg.chemical || '').toLowerCase().startsWith('chlor') ? 'chlorine' : 'alum';
msg.topic = 'rover/dosing/cmd';
msg.payload = JSON.stringify({pump: pump, ml: Number(msg.dose_ml)});
return msg;

if (msg.payload !== true) return null;
msg.payload = 'stop';
return msg;

const s = msg.payload || {};
return [{payload: Number(s.alum_total_ml || 0).toFixed(2) + ' mL'}, {payload: Number(s.chlorine_total_ml || 0).toFixed(2) + ' mL'},
        {payload: Number(s.alum_stock_ml || 0)}, {payload: Number(s.chlorine_stock_ml || 0)}];
